from pathlib import Path
import shutil
R=Path(__file__).resolve().parents[1];D=R/'course-site/dist';(D/'ch4').mkdir(exist_ok=True)
panels=[]
def panel(id,title,body):panels.append((id,title,f'<section class="panel" id="{id}"'+(' hidden'if panels else '')+f'><div class="work-surface"><h2>{title}</h2>{body}</div></section>'))
panel('compare','五种准则比较台','''<p>新校区缺少可信客流概率。先说你重视什么，再选择准则、修改损益、观察推荐。本章不为未知状态偷偷补上概率。</p><div class="compare-controls"><label for="preset">案例<select id="preset"><option value="cafe">新校区咖啡店（模拟）</option><option value="watch">教材例4-3：手表投产</option><option value="regret">教材例4-5：经营方案</option><option value="cost">教材习题2：生产费用</option><option value="equal">教材例4-6：扩大生产</option><option value="books">教材习题6：书店订货</option><option value="auto">教材汽车公司案例</option><option value="extremes">反例：相同极值</option><option value="partition">反例：原来两个状态</option><option value="split">反例：低需求细分</option><option value="alternative">反例：加入新方案</option></select></label><label for="kind">数值含义<select id="kind"><option value="benefit">收益：越大越好</option><option value="cost">成本：越小越好</option></select></label><button id="negate" type="button" class="button secondary">数值取负并切换含义</button></div><p id="case-note" class="notice">教学模拟：快闪、标准、旗舰、不投资；高、中、低需求三状态。金额为全期净现值，单位万元，已扣投资。</p><p class="fine-print">仅切换“数值含义”不会改数字；“取负并切换”同时做 V↔−V 的等价转换。真实收益和真实成本数据不能随意混用。</p><form id="matrix-form"><div id="matrix-editor" class="table-wrap"></div><div class="toolbar"><button id="reset-case" type="button" class="button secondary">恢复本案例</button><label class="alpha-label" for="alpha">乐观系数 α <output id="alpha-out">0.60</output></label><input id="alpha" type="range" min="0" max="1" step="0.01" value="0.6"></div></form><p id="input-error" class="error" role="alert"></p><div class="criterion-tabs" role="group" aria-label="选择查看的准则"><button data-rule="optimistic" aria-pressed="false">乐观</button><button data-rule="pessimistic" aria-pressed="false">悲观</button><button data-rule="hurwicz" aria-pressed="true">折中</button><button data-rule="regret" aria-pressed="false">后悔值</button><button data-rule="laplace" aria-pressed="false">等概率</button></div><div id="criterion-result" class="result-banner" aria-live="polite"></div><p id="criterion-formula" class="formula"></p><div id="criterion-steps" class="table-wrap"></div><details open><summary>五准则并排比较：评分含义不同，不做跨准则加总</summary><div id="all-results" class="table-wrap"></div></details><h3>α 改变时，最优行动在哪里切换？</h3><div id="alpha-chart" class="plot wide"></div><div id="alpha-intervals" class="table-wrap"></div><p id="alpha-points" class="feedback"></p><div class="task-note">C4-E1：默认案例下先预测 α=0、0.4、0.5、1 的最优方案。再修改中需求收益，观察哪些准则改变、哪些没有。记录原因，而不只记录答案。</div>''')
panel('regret-lab','后悔值放大镜','''<p>沿用比较台的当前矩阵。先逐列找该状态最好结果，再做差，最后比较每行的最大机会损失。<a href="#compare">返回编辑数据</a></p><p id="regret-context" class="notice"></p><div class="compare-controls"><label for="focus-state">观察哪个状态<select id="focus-state"></select></label><label for="focus-action">手算哪个方案<select id="focus-action"></select></label></div><div class="toolbar"><button id="reveal" class="button">揭示下一步</button><button id="hide-regret" class="button secondary">重新预测</button></div><p id="regret-stage" class="feedback" aria-live="polite"></p><div class="regret-pair"><div><h3>① 原始矩阵</h3><div id="original-table" class="table-wrap"></div></div><div><h3>② 非负后悔值</h3><div id="regret-table" class="table-wrap"></div></div></div><p id="cell-equation" class="formula"></p><p id="regret-choice" class="result-banner" aria-live="polite"></p><div class="task-note">C4-E2：选“生产费用”案例，先在纸上求三列基准21、24、20，再检验A在状态2的后悔值16。若出现负数，检查减法方向。改变原矩阵后会重新隐藏答案。</div><details><summary>为何教材的成本后悔值有负数？</summary><p>教材p.103使用“列最低成本−本方案成本”，产生非正差额，然后取行最小、再取最大。本课使用其相反数“本方案成本−列最低成本”，然后取行最大、再取最小。二者选择等价，符号和取优方向必须配套。</p></details>''')
panel('limits','用反例检查准则','''<p>以下是独立的小例子。点击按钮会把对应数据送入比较台，便于逐项复算。</p><div class="limit-grid"><article><span class="eyebrow">01 / 只看极值</span><h3>中间结果被藏起来</h3><p>A=[100,0,0,0,0,0]，B=[0,100,80,90,100,100]。两方案最好100、最坏0，任意α下折中得分相同；等权平均则不同。无概率时不能把状态数量直接当发生频率。</p><button class="button secondary" data-case="extremes">比较这组数据</button></article><article><span class="eyebrow">02 / 状态划分</span><h3>只改分类，等权结果也变</h3><p>两个状态时A=[10,0]均值5，B=[4,4]均值4。把低需求分成两个同损益子状态后，A=[10,0,0]均值10/3，B仍为4。重新给每列等权就改变了假设。</p><div class="toolbar"><button class="button secondary" data-case="partition">原来两状态</button><button class="button secondary" data-case="split">细分后三状态</button></div></article><article><span class="eyebrow">03 / 后悔基准</span><h3>新增方案没获选，却改变推荐</h3><p>原来A=[10,0]、B=[4,4]，最大后悔4/6，选A。加入C=[0,10]后，最大后悔10/6/10，改选B。C本身没有获选，但它改变了状态2的比较基准。</p><div class="toolbar"><button class="button secondary" data-case="partition">加入之前</button><button class="button secondary" data-case="alternative">加入之后</button></div></article></div><p class="notice">反例揭示准则关心和忽略的信息。它们不意味着任何选择都同样合理；仍要检查数据、可行性、责任和适用条件。</p>''')
panel('guide','准则与公式速查','''<p>α始终表示乐观系数；本课后悔值始终非负；所有主准则的并列最优都保留。</p><div class="table-wrap"><table><thead><tr><th>准则</th><th>收益：越大越好</th><th>成本：越小越好</th></tr></thead><tbody><tr><td>乐观</td><td>max 行最大值</td><td>min 行最小值</td></tr><tr><td>悲观</td><td>max 行最小值</td><td>min 行最大值</td></tr><tr><td>折中</td><td>max[α行最大+(1−α)行最小]</td><td>min[α行最小+(1−α)行最大]</td></tr><tr><td>后悔值</td><td>R=列最大−原值；min 行最大R</td><td>R=原值−列最小；min 行最大R</td></tr><tr><td>等概率</td><td>max 行算术平均</td><td>min 行算术平均</td></tr></tbody></table></div><h3>三个边界</h3><ol><li>α=0对应悲观，α=1对应乐观；α不是某自然状态的发生概率。</li><li>后悔值为0只说明该方案在这个状态下达到事后最优，不意味着其他状态也最优。</li><li>等概率是建模假设。先定义互斥且穷尽的状态，再讨论等权是否合理。</li></ol><h3>并列时怎么做？</h3><p>先保留全部并列最优。教材p.105对等均值提出辅助比较“均值−最坏收益”，取较小者；若采用请单列说明，不把它称作标准差。本网页不自动套用这个辅助规则。</p><h3>先检查可行性</h3><p>收益高的方案可能因资金、产能或其他硬约束不能实施。先确定可行行动集，再应用准则；行动集变化后，后悔基准也应重算。教材汽车案例的外汇约束就是例子。</p>''')
panel('project','M4 项目与个人测验','''<h3>给已有项目补上概率缺失时的建议</h3><p>在M3档案追加1页及计算附件：说明概率为何不可靠；保留损益和硬约束；列五准则结果、α阈值及后悔表；辩护主准则并提出需要补充的证据。已有可信概率时，可另选新市场情境，不要强行删除信息。</p><p>翻转课堂：3分钟讲解＋2分钟改参质询，先让听众预测，再用一张图或表解释推荐。评分：计算35%、方向与假设25%、准则辩护25%、表达协作15%。</p><p><a href="../downloads/chapter-04-task.md">学生任务单</a> · <a href="../downloads/chapter-04-teacher.md">教师使用指南</a></p><label for="reflection">你的预测、实验记录与准则辩护</label><textarea id="reflection" rows="7" maxlength="12000" placeholder="情境与约束：… 我选择的准则：… 参数与结果：… 反例或边界：… 待补证据：…"></textarea><div class="toolbar"><button id="save-note" class="button secondary">笔记保存在本机</button><button id="export-record" class="button">导出矩阵、结果与笔记 JSON</button></div><p id="note-status" role="status"></p><p class="fine-print">笔记只保存在当前浏览器当前地址，不上传。导出包含当前矩阵、语义、α、计算结果和笔记；换设备前请导出。</p><h3>个人退出测验</h3><form id="quiz-form"><div id="quiz-questions"></div><div class="toolbar"><button type="submit" class="button">提交并查看解释</button><button type="reset" class="button secondary">重新作答</button></div></form><div id="quiz-result" class="feedback" aria-live="polite"></div>''')
panel('sources','教材对应与资料','''<div class="table-wrap"><table><thead><tr><th>节次 / 印刷页码</th><th>学习入口</th></tr></thead><tbody><tr><td>§1 基本概念，p.89—90</td><td>概率缺失与模型条件；演示2—4</td></tr><tr><td>§2—3 乐观、悲观，p.90—96</td><td>五准则比较台；演示6—8</td></tr><tr><td>§4 折中，p.96—101</td><td>α曲线、最优区间、极值反例</td></tr><tr><td>§5 后悔值，p.101—104</td><td>逐列放大镜、收益/成本方向</td></tr><tr><td>§6 等概率，p.104—106</td><td>比较台、状态细分反例</td></tr><tr><td>§7 案例、小结及习题，p.106—110</td><td>汽车案例、附录参考解、M4与测验</td></tr></tbody></table></div><p class="notice">口径说明：成本后悔值采用非负写法；教材负差额写法的取优方向也需反转。教材习题2正文明确为“费用”，本课按成本处理。α=.65的习题4中两个得分仅差0.15，程序保留全精度后显示。</p><p>内容依据项目提供的《决策理论与方法教材（第三版）》；图表与交互独立制作，未复制教材扫描页。新校区数据明确为教学模拟，教材历史案例不作为当前预测。</p><p>交互形式参考 <a href="https://georgec77.github.io/decision-theory-course/" target="_blank" rel="noopener">决策理论与方法交互学习平台</a>。</p><div class="resource-links"><a class="button" href="../downloads/chapter-04.pdf">第四章 PDF</a><a class="button secondary" href="slides.html">演示与逐页讲稿</a><a class="text-link" href="../downloads/chapter-04-coverage.md">知识点覆盖与核对</a></div>''')
nav=''.join(f'<a href="#{id}"'+(' class="active"'if i==0 else '')+f'>{i+1:02d} {title}</a>'for i,(id,title,_)in enumerate(panels))
